import { readFileSync } from "node:fs";

import { expect, sample, test, uniqueName } from "../../fixtures";

const EXPECTED_FIELDS = ["insurer", "policy_number", "coverage_amount", "expiry_date"];

test.describe("Upload vendor documents", () => {
  test(
    "Extraction completes in the background",
    { tag: "@DOC-02" },
    async ({ apiAs }) => {
      // Arrange: signed-in member with a vendor in status "draft"
      const member = await apiAs("member");
      const vendorResponse = await member.post("/api/vendors", {
        data: {
          name: uniqueName("DOC-02 Vendor"),
          category: "services",
          contact_email: `doc02.${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}@northwind.test`,
        },
      });
      expect(vendorResponse.status()).toBe(201);
      const vendor = await vendorResponse.json();
      expect(vendor.status).toBe("draft");

      // Act: upload the insurance certificate as kind "insurance_certificate"
      const uploadResponse = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind: "insurance_certificate",
          file: {
            name: "insurance_certificate.txt",
            mimeType: "text/plain",
            buffer: readFileSync(sample("insurance_certificate.txt")),
          },
        },
      });
      expect(uploadResponse.status()).toBe(201);
      const uploaded = await uploadResponse.json();
      expect(uploaded.kind).toBe("insurance_certificate");

      // Act: wait for background processing to finish
      await expect
        .poll(
          async () => {
            const response = await member.get(`/api/documents/${uploaded.id}`);
            expect(response.status()).toBe(200);
            return (await response.json()).status;
          },
          { timeout: 60_000, intervals: [500, 1000, 2000] },
        )
        .toBe("extracted");

      // Assert: document status is "extracted"
      const documentResponse = await member.get(`/api/documents/${uploaded.id}`);
      expect(documentResponse.status()).toBe(200);
      const document = await documentResponse.json();
      expect(document.status).toBe("extracted");

      // Assert: extraction has the expected fields
      const extractionResponse = await member.get(`/api/documents/${uploaded.id}/extraction`);
      expect(extractionResponse.status()).toBe(200);
      const extraction = await extractionResponse.json();
      expect(Object.keys(extraction.fields).sort()).toEqual([...EXPECTED_FIELDS].sort());

      // Assert: every field has a confidence between 0 and 1
      for (const name of EXPECTED_FIELDS) {
        const field = extraction.fields[name];
        expect(typeof field.confidence, `confidence for ${name}`).toBe("number");
        expect(field.confidence, `confidence for ${name}`).toBeGreaterThanOrEqual(0);
        expect(field.confidence, `confidence for ${name}`).toBeLessThanOrEqual(1);
      }
    },
  );
});
